// utils/iterators/{iterator}/{Iterator}Iterator.ts
// Iterator — parcours de {Iterator} sans révéler la structure interne

export interface {Iterator}Collection {
  data: unknown[]
  meta: {
    current_page:  number
    total_pages:   number
    total_items:   number
  }
}

export class {Iterator}Iterator<T> {
  private currentIndex = 0
  private currentPage  = 1
  private buffer: T[]  = this.collection.data as T[]

  constructor(
    private collection: {Iterator}Collection,
    private fetchNextPage: (page: number) => Promise<{Iterator}Collection>
  ) {}

  async next(): Promise<T | null> {
    if (this.currentIndex >= this.buffer.length) {
      if (this.currentPage >= this.collection.meta.total_pages) return null
      this.currentPage++
      const nextPage   = await this.fetchNextPage(this.currentPage)
      this.buffer      = nextPage.data as T[]
      this.currentIndex = 0
    }
    return this.buffer[this.currentIndex++]
  }

  async hasNext(): Promise<boolean> {
    if (this.currentIndex < this.buffer.length) return true
    return this.currentPage < this.collection.meta.total_pages
  }

  async forEach(callback: (item: T) => void | Promise<void>): Promise<void> {
    let item = await this.next()
    while (item !== null) {
      await callback(item)
      item = await this.next()
    }
  }

  // Collecte tous les éléments (attention à la mémoire sur grandes collections)
  async toArray(): Promise<T[]> {
    const results: T[] = []
    await this.forEach(item => results.push(item))
    return results
  }
}

// composables/{iterator}/use{Iterator}Iterator.ts
import { {Iterator}Iterator } from '~/utils/iterators/{iterator}/{Iterator}Iterator'

export const use{Iterator}Iterator = () => {
  const { apiFetch } = useApi()

  const fetchPage = async (page: number) => {
    return apiFetch<any>(`/{iterator}s`, { query: { page, per_page: 10 } })
  }

  const createIterator = async () => {
    const firstPage = await fetchPage(1)
    return new {Iterator}Iterator(firstPage, fetchPage)
  }

  const iterate = async (callback: (item: unknown) => void | Promise<void>) => {
    const iterator = await createIterator()
    await iterator.forEach(callback)
  }

  return { createIterator, iterate }
}

// tests/utils/iterators/{iterator}/{Iterator}Iterator.spec.ts
import { describe, it, expect, vi } from 'vitest'
import { {Iterator}Iterator } from '~/utils/iterators/{iterator}/{Iterator}Iterator'

const makePage = (items: number[], page: number, totalPages: number) => ({
  data: items,
  meta: { current_page: page, total_pages: totalPages, total_items: items.length * totalPages }
})

describe('{Iterator}Iterator', () => {

  it('next() parcourt les éléments de la première page', async () => {
    const fetch  = vi.fn()
    const iter   = new {Iterator}Iterator(makePage([1, 2, 3], 1, 1), fetch)
    expect(await iter.next()).toBe(1)
    expect(await iter.next()).toBe(2)
    expect(await iter.next()).toBe(3)
    expect(await iter.next()).toBeNull()
  })

  it('next() charge la page suivante automatiquement', async () => {
    const fetch  = vi.fn().mockResolvedValue(makePage([4, 5], 2, 2))
    const iter   = new {Iterator}Iterator(makePage([1, 2, 3], 1, 2), fetch)
    for (let i = 0; i < 3; i++) await iter.next()  // épuise la page 1
    expect(await iter.next()).toBe(4)               // charge page 2
    expect(fetch).toHaveBeenCalledWith(2)
  })

  it('hasNext() retourne false en fin de collection', async () => {
    const iter = new {Iterator}Iterator(makePage([1], 1, 1), vi.fn())
    await iter.next()
    expect(await iter.hasNext()).toBe(false)
  })

  it('forEach() parcourt tous les éléments', async () => {
    const fetch    = vi.fn().mockResolvedValue(makePage([4, 5], 2, 2))
    const iter     = new {Iterator}Iterator(makePage([1, 2, 3], 1, 2), fetch)
    const collected: number[] = []
    await iter.forEach(item => collected.push(item as number))
    expect(collected).toEqual([1, 2, 3, 4, 5])
  })

  it('toArray() retourne tous les éléments', async () => {
    const iter   = new {Iterator}Iterator(makePage([1, 2, 3], 1, 1), vi.fn())
    const result = await iter.toArray()
    expect(result).toEqual([1, 2, 3])
  })

})
